function IsAnagram(s: string, t: string) -> bool {
  if (s.length() != t.length()) {
    return false;
  }
  let counts: map<string, int> = {};
  let sc = s.chars();
  let i = 0;
  while (i < sc.length()) {
    let ch = sc[i];
    let cur = counts.get(ch);
    if (cur == null) {
      counts.set(ch, 1);
    } else {
      counts.set(ch, cur + 1);
    }
    i += 1;
  }
  let tc = t.chars();
  let j = 0;
  while (j < tc.length()) {
    let ch = tc[j];
    let cur = counts.get(ch);
    if (cur == null) {
      return false;
    }
    if (cur == 0) {
      return false;
    }
    counts.set(ch, cur - 1);
    j += 1;
  }
  return true;
}
